import {world,entity,entities,transact,reserveIn,uid,event,today} from "./world.js";
import {esc,money,btn,actions,datePlus,toast} from "./ui.js";
import {go,render} from "./app.js";
import {circuits} from "./circuit-catalog.js";
let selected="pacifico",start="",pax=2;
function items(){const c=circuits[selected],d=start||today();return c.stops.flatMap((s,i)=>{const date=datePlus(d,i);return [...(i?[{service:"circuit-ride-"+c.stops[i-1]+"-"+s,date,qty:pax}]:[]),{service:"circuit-tour-"+s,date,qty:pax},...(i<c.stops.length-1?[{service:"circuit-room-"+s,date,end:datePlus(date,1),qty:Math.ceil(pax/2)}]:[])];});}
export function planner(arg){if(circuits[arg])selected=arg;const c=circuits[selected];return `<div class="container"><div class="section-title"><div><div class="eyebrow">EXPLORA ECUADOR</div><h1>Planifica tu ruta</h1><p>Transporte, alojamiento y experiencias en un solo itinerario.</p></div></div><div class="toolbar">${Object.entries(circuits).map(([id,c])=>btn("chooseCircuit",c.name,id,"chip "+(selected===id?"active":""))).join("")}</div><form id="circuit-form"><div class="panel form-grid"><label>Fecha de inicio<input name="start" type="date" min="${today()}" value="${start||today()}" required></label><label>Viajeros<input name="pax" type="number" min="1" max="8" value="${pax}" required></label></div><h2>${esc(c.name)} · ${c.stops.length} días</h2>${c.stops.map((d,i)=>`<section class="panel"><div class="eyebrow">DÍA ${i+1} · ${datePlus(start||today(),i)}</div><h3>${esc(entity(d).name)}</h3>${items().filter(x=>x.date===datePlus(start||today(),i)).map(x=>`<label class="list-item"><input type="checkbox" name="component" value="${x.service}" checked><span>${esc(entity(x.service).name)}<small> · ${entity(x.service).time||"Noche de alojamiento"}</small></span><strong class="right">${money(entity(x.service).price*x.qty)}</strong></label>`).join("")}</section>`).join("")}<section class="panel"><h2>Total del itinerario <span id="circuit-total">${money(items().reduce((n,x)=>n+entity(x.service).price*x.qty,0))}</span></h2><p>No se realizará ningún cargo.</p><button class="primary" type="submit">Confirmar itinerario</button></section></form></div>`;}
actions.chooseCircuit=({id})=>go("planner/"+id);
document.addEventListener("change",e=>{const f=e.target.closest("#circuit-form");if(!f)return;if(["start","pax"].includes(e.target.name)){start=f.elements.start.value;pax=Number(f.elements.pax.value);render();}else document.querySelector("#circuit-total").textContent=money(items().filter(x=>[...f.querySelectorAll('[name="component"]:checked')].some(el=>el.value===x.service)).reduce((n,x)=>n+entity(x.service).price*x.qty,0));});
document.addEventListener("submit",e=>{if(e.target.id!=="circuit-form")return;e.preventDefault();try{const selectedIds=new FormData(e.target).getAll("component");const list=items().filter(x=>selectedIds.includes(x.service));if(!list.length)throw Error("Selecciona al menos un servicio");transact("circuito",w=>{const id=uid("circuito");w.entities[id]={id,type:"paquete",name:circuits[selected].name,state:"confirmada",date:start||today(),passenger:"viajero-demo"};const rs=reserveIn(w,list,{key:id,packageId:id});w.entities[id].amount=rs.reduce((n,b)=>n+b.amount,0);event(w,"circuito.contratado",id);});go("itinerary");toast("Itinerario confirmado");}catch(err){toast(err.message);}});
